# Capturar errores
casos = [("5", 2), ("abc", 2), ("10", 0)]

for texto, divisor in casos:
    try:
        numero = int(texto)
        resultado = numero / divisor
        print(f"{texto} / {divisor} = {resultado}")
    except ValueError:
        print(f"'{texto}' no es un número")
    except ZeroDivisionError:
        print(f"No se puede dividir {texto} entre 0")

print("\nFin del programa")

def dividir(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None
    finally:
        print(f"  (intento {a}/{b} finalizado)")

print(dividir(10, 2))
print(dividir(10, 0))
print(dividir(20, 4))

class DivergenciaError(Exception):
    """El método se aleja en vez de converger."""
    pass

def raiz_cuadrada(x):
    if x < 0:
        raise ValueError("x debe ser >= 0")
    return x ** 0.5

# Caso válido
print("sqrt(16) =", raiz_cuadrada(16))

# Casos que fallan
try:
    print(raiz_cuadrada(-4))
except ValueError as e:
    print(f"Error: {e}")

try:
    raise DivergenciaError("|x| > 1e6 en iter 5")
except DivergenciaError as e:
    print(f"Error propio: {e}")
